rng = random.Random(8)
layered = {}
for layer in range(30):
    for slot in range(300):
        targets = set(rng.sample(range(300), 3)) if layer < 29 else set()
        layered[f"{layer}-{slot}"] = {f"{layer + 1}-{target}" for target in targets}
assert free_of_deadlock(layered)
for layer in range(29):
    layered[f"{layer}-0"].add(f"{layer + 1}-0")
layered["29-0"] = {"0-0"}
assert deadlocked(layered), "a wait from the last layer back to the first closes a cycle"
